    on_arm do
      url "https://github.com/airiclenz/capcom/releases/download/v0.0.0/capcom_0.0.0_darwin_arm64.tar.gz"
      sha256 "1111111111111111111111111111111111111111111111111111111111111111"
    end
    on_intel do
      url "https://github.com/airiclenz/capcom/releases/download/v0.0.0/capcom_0.0.0_darwin_amd64.tar.gz"
      sha256 "2222222222222222222222222222222222222222222222222222222222222222"
    end
  end

  on_linux do
    on_arm do
      url "https://github.com/airiclenz/capcom/releases/download/v0.0.0/capcom_0.0.0_linux_arm64.tar.gz"
      sha256 "3333333333333333333333333333333333333333333333333333333333333333"
    end
    on_intel do
      url "https://github.com/airiclenz/capcom/releases/download/v0.0.0/capcom_0.0.0_linux_amd64.tar.gz"
      sha256 "4444444444444444444444444444444444444444444444444444444444444444"
    end
  end

  def install
